with open('scripts/create_g3d_day59_data.py', 'r', encoding='utf-8') as f:
    lines = f.readlines()

new_lines = []
current_part = 1
for line in lines:
    if line.strip().startswith('say_p'):
        m = re.match(r'say_p(\d)', line.strip())
        if m:
            current_part = int(m.group(1))
    if 'In the TypeScript snippet below' in line and current_part in extra:
        for p in extra[current_part]:
            new_lines.append(f'    "{p}",\n')
        del extra[current_part]
    new_lines.append(line)

with open('scripts/create_g3d_day59_data.py', 'w', encoding='utf-8') as f:
    f.writelines(new_lines)

print("Updated create_g3d_day59_data.py with all extras!")
